module gcd_table_solver #(\n    parameter N = 4,\n    parameter DATA_WIDTH = 8,\n    parameter MAX_ENTRIES = 16,\n    parameter CLK_PERIOD = 10\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [DATA_WIDTH-1:0] data_in,\n    input wire data_valid,\n    output reg [DATA_WIDTH-1:0] result,\n    output reg result_valid,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE               = 4'd0;\n    localparam [3:0] S_INPUT              = 4'd1;\n    localparam [3:0] S_SORT               = 4'd2;\n    localparam [3:0] S_BUILD_DISTINCT     = 4'd3;\n    localparam [3:0] S_FIND_CANDIDATE     = 4'd4;\n    localparam [3:0] S_DECREMENT_CANDIDATE= 4'd5;\n    localparam [3:0] S_PROCESS_RESULTS    = 4'd6;\n    localparam [3:0] S_COMPUTE_GCD        = 4'd7;\n    localparam [3:0] S_FIND_GCD           = 4'd8;\n    localparam [3:0] S_DECREMENT_GCD      = 4'd9;\n    localparam [3:0] S_APPEND_RESULT      = 4'd10;\n    localparam [3:0] S_OUTPUT             = 4'd11;\n    localparam [3:0] S_DONE               = 4'd12;\n\n    // Internal registers\n    reg [3:0] state, next_state;\n    reg [DATA_WIDTH-1:0] buffer [0:MAX_ENTRIES-1];\n    reg [DATA_WIDTH-1:0] distinct_nums [0:MAX_ENTRIES-1];\n    reg [DATA_WIDTH-1:0] distinct_counts [0:MAX_ENTRIES-1];\n    reg [DATA_WIDTH-1:0] result_arr [0:N-1];\n    reg [DATA_WIDTH-1:0] temp_buffer [0:MAX_ENTRIES-1];\n    reg [DATA_WIDTH-1:0] sorted_buffer [0:MAX_ENTRIES-1];\n    \n    reg [DATA_WIDTH-1:0] buffer_idx;\n    reg [DATA_WIDTH-1:0] distinct_idx;\n    reg [DATA_WIDTH-1:0] distinct_count_idx;\n    reg [DATA_WIDTH-1:0] result_idx;\n    reg [DATA_WIDTH-1:0] candidate_idx;\n    reg [DATA_WIDTH-1:0] process_idx;\n    reg [DATA_WIDTH-1:0] gcd_idx;\n    reg [DATA_WIDTH-1:0] output_idx;\n    reg [DATA_WIDTH-1:0] candidate_value;\n    reg [DATA_WIDTH-1:0] candidate_count;\n    reg [DATA_WIDTH-1:0] process_value;\n    reg [DATA_WIDTH-1:0] gcd_a;\n    reg [DATA_WIDTH-1:0] gcd_b;\n    reg [DATA_WIDTH-1:0] gcd_result;\n    reg [DATA_WIDTH-1:0] gcd_rem;\n    reg [DATA_WIDTH-1:0] cycle_count;\n    reg [DATA_WIDTH-1:0] sort_pass;\n    reg [DATA_WIDTH-1:0] sort_i;\n    reg [DATA_WIDTH-1:0] gcd_cycles;\n    reg [DATA_WIDTH-1:0] distinct_count;\n    reg [DATA_WIDTH-1:0] result_count;\n    reg [DATA_WIDTH-1:0] sort_swapped;\n    reg [DATA_WIDTH-1:0] gcd_temp_a;\n    reg [DATA_WIDTH-1:0] gcd_temp_b;\n    reg [DATA_WIDTH-1:0] find_gcd_idx;\n    reg [DATA_WIDTH-1:0] temp_gcd;\n    reg [DATA_WIDTH-1:0] decrement_target_idx;\n    reg [DATA_WIDTH-1:0] decrement_amount;\n    reg [DATA_WIDTH-1:0] output_temp;\n\n    // GCD function (iterative, simplified for synthesis)\n    // Returns gcd of a and b\n    function automatic [7:0] compute_gcd(input [7:0] a, input [7:0] b);\n        reg [7:0] t_a, t_b, t_rem;\n        begin\n            t_a = a;\n            t_b = b;\n            while (t_b != 8'd0) begin\n                t_rem = t_a % t_b;\n                t_a = t_b;\n                t_b = t_rem;\n            end\n            compute_gcd = t_a;\n        end\n    endfunction\n\n    // Combinational logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            S_IDLE: begin\n                if (start) next_state = S_INPUT;\n            end\n            S_INPUT: begin\n                if (buffer_idx >= MAX_ENTRIES) next_state = S_SORT;\n                else if (data_valid) next_state = S_INPUT; // Stay until all received\n            end\n            S_SORT: begin\n                if (sort_pass >= MAX_ENTRIES-1) next_state = S_BUILD_DISTINCT;\n                else next_state = S_SORT;\n            end\n            S_BUILD_DISTINCT: begin\n                if (buffer_idx >= MAX_ENTRIES) next_state = S_FIND_CANDIDATE;\n                else next_state = S_BUILD_DISTINCT;\n            end\n            S_FIND_CANDIDATE: begin\n                if (distinct_count_idx >= distinct_count) begin\n                    if (result_idx == N) next_state = S_OUTPUT;\n                    else next_state = S_APPEND_RESULT;\n                end else begin\n                    next_state = S_FIND_CANDIDATE;\n                end\n            end\n            S_DECREMENT_CANDIDATE: begin\n                next_state = S_PROCESS_RESULTS;\n            end\n            S_PROCESS_RESULTS: begin\n                if (process_idx >= result_idx) next_state = S_APPEND_RESULT;\n                else next_state = S_COMPUTE_GCD;\n            end\n            S_COMPUTE_GCD: begin\n                next_state = S_FIND_GCD;\n            end\n            S_FIND_GCD: begin\n                if (find_gcd_idx >= distinct_count) next_state = S_DECREMENT_GCD;\n                else next_state = S_FIND_GCD;\n            end\n            S_DECREMENT_GCD: begin\n                if (gcd_idx < result_idx) next_state = S_PROCESS_RESULTS;\n                else next_state = S_APPEND_RESULT;\n            end\n            S_APPEND_RESULT: begin\n                next_state = S_FIND_CANDIDATE;\n            end\n            S_OUTPUT: begin\n                if (output_idx >= result_idx) next_state = S_DONE;\n                else next_state = S_OUTPUT;\n            end\n            S_DONE: begin\n                next_state = S_IDLE;\n            end\n            default: next_state = S_IDLE;\n        endcase\n    end\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            buffer_idx <= 8'd0;\n            distinct_idx <= 8'd0;\n            distinct_count_idx <= 8'd0;\n            result_idx <= 8'd0;\n            candidate_idx <= 8'd0;\n            process_idx <= 8'd0;\n            gcd_idx <= 8'd0;\n            output_idx <= 8'd0;\n            candidate_value <= 8'd0;\n            candidate_count <= 8'd0;\n            process_value <= 8'd0;\n            gcd_a <= 8'd0;\n            gcd_b <= 8'd0;\n            gcd_result <= 8'd0;\n            gcd_rem <= 8'd0;\n            cycle_count <= 8'd0;\n            sort_pass <= 8'd0;\n            sort_i <= 8'd0;\n            gcd_cycles <= 8'd0;\n            distinct_count <= 8'd0;\n            sort_swapped <= 8'd0;\n            gcd_temp_a <= 8'd0;\n            gcd_temp_b <= 8'd0;\n            find_gcd_idx <= 8'd0;\n            temp_gcd <= 8'd0;\n            decrement_target_idx <= 8'd0;\n            decrement_amount <= 8'd0;\n            output_temp <= 8'd0;\n            result <= 8'd0;\n            result_valid <= 1'b0;\n            done <= 1'b0;\n            // Initialize arrays\n            for (integer i = 0; i < MAX_ENTRIES; i = i + 1) begin\n                buffer[i] <= 8'd0;\n                distinct_nums[i] <= 8'd0;\n                distinct_counts[i] <= 8'd0;\n                temp_buffer[i] <= 8'd0;\n                sorted_buffer[i] <= 8'd0;\n            end\n            for (integer i = 0; i < N; i = i + 1) begin\n                result_arr[i] <= 8'd0;\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    buffer_idx <= 8'd0;\n                    distinct_idx <= 8'd0;\n                    result_idx <= 8'd0;\n                    cycle_count <= 8'd0;\n                    result_valid <= 1'b0;\n                end\n                S_INPUT: begin\n                    if (data_valid && buffer_idx < MAX_ENTRIES) begin\n                        buffer[buffer_idx] <= data_in;\n                        buffer_idx <= buffer_idx + 8'd1;\n                    end\n                end\n                S_SORT: begin\n                    // Bubble sort implementation\n                    if (sort_pass < MAX_ENTRIES-1) begin\n                        sort_swapped <= 8'd0;\n                        if (sort_i < MAX_ENTRIES-1) begin\n                            if (buffer[sort_i] < buffer[sort_i+1]) begin\n                                // Swap\n                                sorted_buffer[sort_i] <= buffer[sort_i+1];\n                                sorted_buffer[sort_i+1] <= buffer[sort_i];\n                                buffer[sort_i] <= buffer[sort_i+1];\n                                buffer[sort_i+1] <= buffer[sort_i];\n                                sort_swapped <= 8'd1;\n                            end\n                            sort_i <= sort_i + 8'd1;\n                        end else begin\n                            sort_i <= 8'd0;\n                            sort_pass <= sort_pass + 8'd1;\n                        end\n                    end\n                end\n                S_BUILD_DISTINCT: begin\n                    if (buffer_idx < MAX_ENTRIES) begin\n                        if (buffer_idx == 8'd0 || buffer[buffer_idx] != buffer[buffer_idx-1]) begin\n                            distinct_nums[distinct_idx] <= buffer[buffer_idx];\n                            distinct_counts[distinct_idx] <= 8'd1;\n                            distinct_idx <= distinct_idx + 8'd1;\n                            distinct_count <= distinct_count + 8'd1;\n                        end else begin\n                            distinct_counts[distinct_idx-1] <= distinct_counts[distinct_idx-1] + 8'd1;\n                        end\n                        buffer_idx <= buffer_idx + 8'd1;\n                    end\n                end\n                S_FIND_CANDIDATE: begin\n                    if (distinct_count_idx < distinct_count) begin\n                        if (distinct_counts[distinct_count_idx] > 8'd0) begin\n                            candidate_value <= distinct_nums[distinct_count_idx];\n                            candidate_count <= distinct_counts[distinct_count_idx];\n                            candidate_idx <= distinct_count_idx;\n                            distinct_count_idx <= distinct_count; // Skip remaining\n                        end\n                        distinct_count_idx <= distinct_count_idx + 8'd1;\n                    end\n                end\n                S_DECREMENT_CANDIDATE: begin\n                    if (candidate_count > 8'd0) begin\n                        distinct_counts[candidate_idx] <= candidate_count - 8'd1;\n                    end\n                    process_idx <= 8'd0;\n                    gcd_idx <= 8'd0;\n                end\n                S_PROCESS_RESULTS: begin\n                    if (process_idx < result_idx) begin\n                        process_value <= result_arr[process_idx];\n                    end\n                end\n                S_COMPUTE_GCD: begin\n                    gcd_a <= candidate_value;\n                    gcd_b <= process_value;\n                    gcd_temp_a <= candidate_value;\n                    gcd_temp_b <= process_value;\n                    gcd_cycles <= 8'd0;\n                    temp_gcd <= candidate_value;\n                    find_gcd_idx <= 8'd0;\n                end\n                S_FIND_GCD: begin\n                    // Simplified GCD computation\n                    if (find_gcd_idx < 8'd8 && gcd_temp_b != 8'd0) begin\n                        gcd_rem <= gcd_temp_a % gcd_temp_b;\n                        gcd_temp_a <= gcd_temp_b;\n                        gcd_temp_b <= gcd_rem;\n                        temp_gcd <= gcd_temp_b;\n                        find_gcd_idx <= find_gcd_idx + 8'd1;\n                    end else begin\n                        gcd_result <= temp_gcd;\n                    end\n                end\n                S_DECREMENT_GCD: begin\n                    if (gcd_idx < distinct_count) begin\n                        if (distinct_nums[gcd_idx] == gcd_result && distinct_counts[gcd_idx] >= 2) begin\n                            distinct_counts[gcd_idx] <= distinct_counts[gcd_idx] - 8'd2;\n                        end\n                    end\n                    gcd_idx <= gcd_idx + 8'd1;\n                    process_idx <= process_idx + 8'd1;\n                end\n                S_APPEND_RESULT: begin\n                    if (result_idx < N) begin\n                        result_arr[result_idx] <= candidate_value;\n                        result_idx <= result_idx + 8'd1;\n                    end\n                    distinct_count_idx <= 8'd0;\n                end\n                S_OUTPUT: begin\n                    result_valid <= 1'b1;\n                    if (output_idx < result_idx) begin\n                        result <= result_arr[output_idx];\n                        output_idx <= output_idx + 8'd1;\n                    end\n                end\n                S_DONE: begin\n                    done <= 1'b1;\n                    result_valid <= 1'b0;\n                end\n            endcase\n        end\n    end\nendmodule